insert into practice_context_blocks (id, exercise_id, label, image_url, text_content, block_type) values
  ('dfd82f19-e9ec-4d75-9e97-91e461524a75', '98afa037-dc66-405a-9594-45d3db93630a', $$inleiding: fietsenmaker Juul Appelboom specialiseert zich in e-bikes van enkele merken$$,
   $$bedrijfseconomie-vwo-2024-ii-juul-appelboom-context1.png$$,
   $$Fietsenmaker Juul Appelboom heeft op basis van een SWOT-analyse de strategische keuze gemaakt om zich te specialiseren in de verkoop en het onderhoud van e-bikes van slechts enkele fietsmerken. Met de komst van de e-bike is het beroep van de fietsenmaker ingrijpend veranderd.
In het oude bedrijfsmodel verkocht en repareerde Juul vele typen fietsen (stadsfietsen, mountainbikes en e-bikes) van verschillende merken. Klanten konden zonder afspraak terecht voor kleine reparaties. De monteur kon hierdoor minder snel werken, omdat er vaak kleine reparaties tussendoor werden gedaan.
De laatste jaren merkte Juul dat het bijhouden van de kennis over het repareren van e-bikes van verschillende merken bijna onmogelijk was geworden, doordat e-bikes steeds complexer zijn geworden. Hij heeft zich daarom gespecialiseerd in de verkoop en het onderhoud van e-bikes van enkele fietsmerken. Van deze merken weet hij precies hoe de fietsen gemaakt zijn en onderhouden moeten worden.$$, 'inline'),
  ('3d1f9b61-ff8f-411c-b04a-44a73258d5ad', '98afa037-dc66-405a-9594-45d3db93630a', $$gemoderniseerde winkel en aanpassingen in het bedrijfsmodel$$,
   $$bedrijfseconomie-vwo-2024-ii-juul-appelboom-context2.png$$,
   $$Zijn fietsenwinkel heeft hij in samenwerking met een grote leverancier van e-bikes in een nieuw jasje gestoken. De winkelinrichting, etalage en werkplaats zijn volledig gemoderniseerd.
Verdere aanpassingen die fietsenmaker Juul heeft doorgevoerd:
− Via een eigen YouTubekanaal geeft Juul tips over de aankoop van een e-bike.
− Om sneller te kunnen werken, wordt er alleen nog op afspraak gewerkt.
− Juul repareert alleen nog maar e-bikes die bij hem zijn gekocht.
Het nieuwe bedrijfsmodel van Juuls fietsenwinkel kan leiden tot kostenbesparingen.$$, 'inline'),
  ('218c665f-7983-40c6-ad3d-1cf3c70e135f', '98afa037-dc66-405a-9594-45d3db93630a', $$groter bereik en andere beleving; twee instrumenten van de marketingmix veranderd$$,
   $$bedrijfseconomie-vwo-2024-ii-juul-appelboom-context3.png$$,
   $$Als gevolg van de aanpassingen heeft de nieuwe winkel van Juul een groter bereik en geeft die een andere beleving bij klanten. Klanten zijn zelfs bereid om een uur te rijden om in zijn winkel een e-bike te kopen. Juul heeft de invulling van twee instrumenten van de marketingmix veranderd.$$, 'inline'),
  ('06d19cb0-850f-4652-b28c-705f1a4e5394', '98afa037-dc66-405a-9594-45d3db93630a', $$verkoop van twee e-bikes op rekening per 1 juni 2023$$,
   $$bedrijfseconomie-vwo-2024-ii-juul-appelboom-context4.png$$,
   $$(Foto van een e-bike)
Juul verkoopt per 1 juni 2023 twee e-bikes op rekening van € 2.450 per stuk exclusief 21% btw. De klant neemt de fietsen direct mee. De winst bedraagt 40% van de inkoopwaarde van de omzet.$$, 'inline'),
  ('c93f9151-795c-4e5b-834e-b5e93bd5bd4e', '98afa037-dc66-405a-9594-45d3db93630a', $$Uitwerkbijlage vraag 1$$,
