  ('7f27053a-8987-4be8-98bd-12aef22f0dc4', '98afa037-dc66-405a-9594-45d3db93630a', $$Uitwerkbijlage vraag 5$$,
   $$bedrijfseconomie-vwo-2024-ii-juul-appelboom-uitwerkbijlage5.png$$,
