  ('4479c285-ee4f-49a0-920b-c1c3400ff16e', 'cb4b558b-157b-466b-bb56-414afb1e3f16', $$nominale waarde € 25 per aandeel; balansbedragen als gemiddelden$$,
   $$bedrijfseconomie-vwo-2024-ii-leijten-nv-context4.png$$,
